INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 4, 'konten', 'ja', '<p style=\"text-align: left;\">村役場では、各種証明書の申請手続きを迅速に行っており、通常1営業日以内に発行いたします。住民の皆様は、以下の必要書類をご準備ください。<br>1. 居住証明書・事業証明書・生活困窮証明書<br>以下の書類をご持参ください。<br>身分証明書（KTP）のコピー<br>家族カード（KK）のコピー<br>お住まいの地域のRT/RW代表者による紹介状<br>2. 身分証明書（KTP）・家族カード（KK）の申請用紹介状<br>以下のいずれかをご持参ください。<br>F1.01申請書<br>更新する家族カード（KK）の原本<br>受付時間： 月曜日～金曜日　8:00～16:00（WIB）<br>受付場所： クレゴ村役場</p>') ON DUPLICATE KEY UPDATE teks_terjemahan='<p style=\"text-align: left;\">村役場では、各種証明書の申請手続きを迅速に行っており、通常1営業日以内に発行いたします。住民の皆様は、以下の必要書類をご準備ください。<br>1. 居住証明書・事業証明書・生活困窮証明書<br>以下の書類をご持参ください。<br>身分証明書（KTP）のコピー<br>家族カード（KK）のコピー<br>お住まいの地域のRT/RW代表者による紹介状<br>2. 身分証明書（KTP）・家族カード（KK）の申請用紹介状<br>以下のいずれかをご持参ください。<br>F1.01申請書<br>更新する家族カード（KK）の原本<br>受付時間： 月曜日～金曜日　8:00～16:00（WIB）<br>受付場所： クレゴ村役場</p>';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 3, 'judul', 'ja', 'クレゴ村の魅力とUMKM') ON DUPLICATE KEY UPDATE teks_terjemahan='クレゴ村の魅力とUMKM';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 3, 'konten', 'ja', '<p style=\"text-align: left;\">クレゴ村は、312ヘクタールを超える生産性の高い農地に恵まれ、付加価値の高い主要農産物を生産しています。&nbsp;また、農業分野だけでなく、87の零細・中小企業（UMKM）が地域経済を支える重要な存在として発展しており、主な産業は以下のとおりです。</p>\r\n<ol>\r\n<li>輸出品質の竹・木工編み細工</li>\r\n<li>地元農産物を活用した伝統食品・加工食品</li>\r\n<li>手描きバティック（バティック・トゥリス）および縫製産業</li>\r\n</ol>') ON DUPLICATE KEY UPDATE teks_terjemahan='<p style=\"text-align: left;\">クレゴ村は、312ヘクタールを超える生産性の高い農地に恵まれ、付加価値の高い主要農産物を生産しています。&nbsp;また、農業分野だけでなく、87の零細・中小企業（UMKM）が地域経済を支える重要な存在として発展しており、主な産業は以下のとおりです。</p>\r\n<ol>\r\n<li>輸出品質の竹・木工編み細工</li>\r\n<li>地元農産物を活用した伝統食品・加工食品</li>\r\n<li>手描きバティック（バティック・トゥリス）および縫製産業</li>\r\n</ol>';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 2, 'judul', 'ja', 'クレゴ村の行政組織') ON DUPLICATE KEY UPDATE teks_terjemahan='クレゴ村の行政組織';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 2, 'konten', 'ja', '<p>クレゴ村役場の組織体制（SOTK）</p>\r\n<p>クレゴ村役場は、迅速かつ一体的な行政サービスの提供を目指しています。村長をはじめとする職員一同は、住民の行政手続きの円滑な実施と地域の発展を支えるため、常に取り組んでいます。<br>現在、クレゴ村は5つの集落 、6つのRW、18のRTで構成されています。</p>\r\n<p>役職や担当業務などの詳細につきましては、平日の開庁時間内に村役場までお気軽にお問い合わせください。</p>') ON DUPLICATE KEY UPDATE teks_terjemahan='<p>クレゴ村役場の組織体制（SOTK）</p>\r\n<p>クレゴ村役場は、迅速かつ一体的な行政サービスの提供を目指しています。村長をはじめとする職員一同は、住民の行政手続きの円滑な実施と地域の発展を支えるため、常に取り組んでいます。<br>現在、クレゴ村は5つの集落 、6つのRW、18のRTで構成されています。</p>\r\n<p>役職や担当業務などの詳細につきましては、平日の開庁時間内に村役場までお気軽にお問い合わせください。</p>';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 1, 'judul', 'ja', 'クレゴ村の歴史とビジョン・ミッション') ON DUPLICATE KEY UPDATE teks_terjemahan='クレゴ村の歴史とビジョン・ミッション';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 1, 'konten', 'ja', '<figure style=\"margin: 24px auto; text-align: center; display: block; clear: both;\"><img style=\"max-width: 100%; height: 331px; border-radius: 12px; box-shadow: rgba(0, 0, 0, 0.12) 0px 10px 25px -5px; display: block; margin: 0px auto; border: 1px solid rgb(226, 232, 240);\" src=\"../uploads/editor/img_20260804_022807_6a713217d2582.jpeg\" alt=\"Gambar Bukti\" width=\"228\"></figure>\r\n<p>&nbsp;</p>\r\n<p>村長のビジョン</p>\r\n<p>「説明責任のある行政運営を通じて、豊かで自立し、文化を大切にし、透明性の高いクレゴ村の実現を目指します。」</p>\r\n<p>クレゴ村のミッション</p>\r\n<p>- 情報技術（IT）を活用し、クレゴ村の全住民に対する行政サービスの質を向上させます。<br>- 村内すべての集落において、道路や公共施設などの社会基盤を計画的かつ持続的に整備します。<br>- 近代的な農業の推進とUMKM（零細・中小企業）の育成を通じて、地域経済の発展を図ります。<br>- 情報公開を積極的に進めるとともに、透明性が高く、適切な予算運営を実現します。</p>\r\n<p>クレゴ村の沿革</p>\r\n<p>クレゴ村は、ボヨラリ県の戦略的な地域に位置しています。古くから地域経済の発展を支える拠点であるとともに、公平な農業地域として知られてきました。現在では、その伝統を受け継ぎながら、競争力の高い近代的な行政を目指して発展を続けています.</p>') ON DUPLICATE KEY UPDATE teks_terjemahan='<figure style=\"margin: 24px auto; text-align: center; display: block; clear: both;\"><img style=\"max-width: 100%; height: 331px; border-radius: 12px; box-shadow: rgba(0, 0, 0, 0.12) 0px 10px 25px -5px; display: block; margin: 0px auto; border: 1px solid rgb(226, 232, 240);\" src=\"../uploads/editor/img_20260804_022807_6a713217d2582.jpeg\" alt=\"Gambar Bukti\" width=\"228\"></figure>\r\n<p>&nbsp;</p>\r\n<p>村長のビジョン</p>\r\n<p>「説明責任のある行政運営を通じて、豊かで自立し、文化を大切にし、透明性の高いクレゴ村の実現を目指します。」</p>\r\n<p>クレゴ村のミッション</p>\r\n<p>- 情報技術（IT）を活用し、クレゴ村の全住民に対する行政サービスの質を向上させます。<br>- 村内すべての集落において、道路や公共施設などの社会基盤を計画的かつ持続的に整備します。<br>- 近代的な農業の推進とUMKM（零細・中小企業）の育成を通じて、地域経済の発展を図ります。<br>- 情報公開を積極的に進めるとともに、透明性が高く、適切な予算運営を実現します。</p>\r\n<p>クレゴ村の沿革</p>\r\n<p>クレゴ村は、ボヨラリ県の戦略的な地域に位置しています。古くから地域経済の発展を支える拠点であるとともに、公平な農業地域として知られてきました。現在では、その伝統を受け継ぎながら、競争力の高い近代的な行政を目指して発展を続けています.</p>';
