INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 4, 'judul', 'en', 'Community Administrative Services Guide') ON DUPLICATE KEY UPDATE teks_terjemahan='Community Administrative Services Guide';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 4, 'konten', 'en', '<p>Easy &amp; Fast Services at Klego Village Office</p>\r\n<p><br>The Village Government provides fast processing of administrative certificates, with completion within one business day. Residents are requested to prepare the following required documents:</p>\r\n<ol>\r\n<li>Certificate of Residence / Business Certificate / Certificate of Indigency: Bring a photocopy of your National ID Card (KTP), Family Card (KK), and a recommendation letter from the local RT/RW head.</li>\r\n<li>Introduction Letter for National ID Card (KTP) / Family Card (KK): Bring the F1.01 form or the original Family Card (KK) to be updated.</li>\r\n</ol>\r\n<p>Office hours: Monday to Friday, 08:00 AM &ndash; 04:00 PM (WIB) at the Klego Village Office.</p>') ON DUPLICATE KEY UPDATE teks_terjemahan='<p>Easy &amp; Fast Services at Klego Village Office</p>\r\n<p><br>The Village Government provides fast processing of administrative certificates, with completion within one business day. Residents are requested to prepare the following required documents:</p>\r\n<ol>\r\n<li>Certificate of Residence / Business Certificate / Certificate of Indigency: Bring a photocopy of your National ID Card (KTP), Family Card (KK), and a recommendation letter from the local RT/RW head.</li>\r\n<li>Introduction Letter for National ID Card (KTP) / Family Card (KK): Bring the F1.01 form or the original Family Card (KK) to be updated.</li>\r\n</ol>\r\n<p>Office hours: Monday to Friday, 08:00 AM &ndash; 04:00 PM (WIB) at the Klego Village Office.</p>';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 3, 'judul', 'en', 'Potentials & UMKM of Klego Village') ON DUPLICATE KEY UPDATE teks_terjemahan='Potentials & UMKM of Klego Village';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 3, 'konten', 'en', '<p>Potentials &amp; UMKM of Klego Village<br>Agricultural Excellence &amp; MSME Products<br>Klego Village is blessed with more than 312 hectares of productive agricultural land, producing high-value staple crops. In addition to its strong agricultural sector, the village is home to 87 Micro, Small, and Medium Enterprises (MSMEs) that contribute significantly to the local economy, including:</p>\r\n<ul>\r\n<li>Export-quality bamboo and wooden handicrafts.</li>\r\n<li>Processed local and traditional food products.</li>\r\n<li>Handmade batik and local garment production.</li>\r\n</ul>') ON DUPLICATE KEY UPDATE teks_terjemahan='<p>Potentials &amp; UMKM of Klego Village<br>Agricultural Excellence &amp; MSME Products<br>Klego Village is blessed with more than 312 hectares of productive agricultural land, producing high-value staple crops. In addition to its strong agricultural sector, the village is home to 87 Micro, Small, and Medium Enterprises (MSMEs) that contribute significantly to the local economy, including:</p>\r\n<ul>\r\n<li>Export-quality bamboo and wooden handicrafts.</li>\r\n<li>Processed local and traditional food products.</li>\r\n<li>Handmade batik and local garment production.</li>\r\n</ul>';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 2, 'judul', 'en', 'Organizational Structure of Klego Village Government') ON DUPLICATE KEY UPDATE teks_terjemahan='Organizational Structure of Klego Village Government';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 2, 'konten', 'en', '<p>Organizational Structure and Work Procedures (SOTK) of Klego Village Government</p>\r\n<p><br>The Klego Village Government is committed to providing fast and integrated public services. The Village Head and all village officials work together to ensure efficient administrative services and support sustainable development across 5 hamlets, 6 neighborhood associations (RW), and 18 community units (RT) in Klego Village.</p>\r\n<p>For detailed information regarding village officials, their positions, and responsibilities, residents may visit the Klego Village Office during regular office hours.</p>') ON DUPLICATE KEY UPDATE teks_terjemahan='<p>Organizational Structure and Work Procedures (SOTK) of Klego Village Government</p>\r\n<p><br>The Klego Village Government is committed to providing fast and integrated public services. The Village Head and all village officials work together to ensure efficient administrative services and support sustainable development across 5 hamlets, 6 neighborhood associations (RW), and 18 community units (RT) in Klego Village.</p>\r\n<p>For detailed information regarding village officials, their positions, and responsibilities, residents may visit the Klego Village Office during regular office hours.</p>';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 1, 'judul', 'en', 'History, Vision & Mission of Klego Village') ON DUPLICATE KEY UPDATE teks_terjemahan='History, Vision & Mission of Klego Village';
INSERT INTO terjemahan_konten (kategori, referensi_id, kunci, kode_bahasa, teks_terjemahan) VALUES ('halaman', 1, 'konten', 'en', '<figure style=\"margin: 24px auto; text-align: center; display: block; clear: both;\"><img style=\"max-width: 100%; height: 331px; border-radius: 12px; box-shadow: rgba(0, 0, 0, 0.12) 0px 10px 25px -5px; display: block; margin: 0px auto; border: 1px solid rgb(226, 232, 240);\" src=\"../uploads/editor/img_20260804_022807_6a713217d2582.jpeg\" alt=\"Gambar Bukti\" width=\"228\"></figure>\r\n<p>&nbsp;</p>\r\n<p>History, Vision &amp; Mission of Klego Village</p>\r\n<p>Village Head\'s Vision<br>\"To build a prosperous, independent, culturally rich, and transparent Klego Village through accountable governance.\"</p>\r\n<p>Village Mission<br>- Improve the quality of public administrative services for all residents of Klego Village through the use of information technology.<br>- Develop road infrastructure and community facilities evenly and sustainably across all hamlets.<br>- Strengthen the local economy through modern agriculture and the empowerment of Micro, Small, and Medium Enterprises (MSMEs).<br>- Promote public information transparency and ensure accountable, transparent, and well-targeted budget management.</p>\r\n<p><br>Brief History of Klego Village<br>Klego Village is strategically located in Boyolali Regency. Since ancient times, the village has been recognized as a center of local economic growth and a fair agricultural region. Today, it continues to evolve into a modern, competitive village government while preserving its rich heritage.</p>') ON DUPLICATE KEY UPDATE teks_terjemahan='<figure style=\"margin: 24px auto; text-align: center; display: block; clear: both;\"><img style=\"max-width: 100%; height: 331px; border-radius: 12px; box-shadow: rgba(0, 0, 0, 0.12) 0px 10px 25px -5px; display: block; margin: 0px auto; border: 1px solid rgb(226, 232, 240);\" src=\"../uploads/editor/img_20260804_022807_6a713217d2582.jpeg\" alt=\"Gambar Bukti\" width=\"228\"></figure>\r\n<p>&nbsp;</p>\r\n<p>History, Vision &amp; Mission of Klego Village</p>\r\n<p>Village Head\'s Vision<br>\"To build a prosperous, independent, culturally rich, and transparent Klego Village through accountable governance.\"</p>\r\n<p>Village Mission<br>- Improve the quality of public administrative services for all residents of Klego Village through the use of information technology.<br>- Develop road infrastructure and community facilities evenly and sustainably across all hamlets.<br>- Strengthen the local economy through modern agriculture and the empowerment of Micro, Small, and Medium Enterprises (MSMEs).<br>- Promote public information transparency and ensure accountable, transparent, and well-targeted budget management.</p>\r\n<p><br>Brief History of Klego Village<br>Klego Village is strategically located in Boyolali Regency. Since ancient times, the village has been recognized as a center of local economic growth and a fair agricultural region. Today, it continues to evolve into a modern, competitive village government while preserving its rich heritage.</p>';
